// Fetch deals pending CRM sync
console.log('Fetching deals for CRM sync');

// In production, fetch from database where crm_synced = false
// For demo, generate sample deals
const deals = [];

for (let i = 0; i < 15; i++) {
  deals.push({
    propertyId: `prop-${Date.now()}-${i}`,
    address: `${1000 + i} Main St`,
    city: ['Austin', 'Dallas', 'Houston'][i % 3],
    state: 'TX',
    zipCode: String(78701 + i),
    listPrice: Math.floor(Math.random() * 4000000) + 1000000,
    propertyType: ['multifamily', 'retail', 'office'][i % 3],
    squareFeet: Math.floor(Math.random() * 40000) + 10000,
    dealScore: Math.floor(Math.random() * 30) + 70,
    dealTier: ['S', 'A', 'B'][i % 3],
    capRate: (Math.random() * 3 + 6).toFixed(2),
    irr: (Math.random() * 8 + 12).toFixed(2),
    ownerName: `Owner ${i} LLC`,
    ownerEmail: `owner${i}@example.com`,
    ownerPhone: `+1-512-555-${String(i).padStart(4, '0')}`,
    recommendation: ['STRONG BUY', 'BUY', 'CONSIDER'][i % 3],
    scoredAt: new Date().toISOString()
  });
}

return deals.map(deal => ({ json: deal }));

// Format deal for Airtable
const deal = $input.item.json;

// Airtable record structure
const airtableRecord = {
  fields: {
    'Property ID': deal.propertyId,
    'Address': deal.address,
    'City': deal.city,
    'State': deal.state,
    'Zip Code': deal.zipCode,
    'Full Address': `${deal.address}, ${deal.city}, ${deal.state} ${deal.zipCode}`,

    // Financial fields
    'List Price': deal.listPrice,
    'Cap Rate': parseFloat(deal.capRate),
    'Projected IRR': parseFloat(deal.irr),
    'Price per SF': Math.round(deal.listPrice / deal.squareFeet),

    // Property details
    'Property Type': deal.propertyType,
    'Square Feet': deal.squareFeet,

    // Deal scoring
    'Deal Score': deal.dealScore,
    'Deal Tier': deal.dealTier,
    'Recommendation': deal.recommendation,

    // Owner information
    'Owner Name': deal.ownerName,
    'Owner Email': deal.ownerEmail,
    'Owner Phone': deal.ownerPhone,

    // Status fields
    'Status': 'New',
    'Stage': 'Lead',
    'Assigned To': deal.dealScore >= 85 ? 'Managing Partner' : 'Analyst',

    // Timestamps
    'Created': deal.scoredAt,
    'Last Updated': new Date().toISOString(),

    // Metadata
    'Source': 'PropFlow Engine',
    'Sync Date': new Date().toISOString()
  }
};

return [{
  json: {
    deal: deal,
    airtableRecord: airtableRecord
  }
}];

// Simulate Airtable upsert operation
const data = $input.item.json;
const deal = data.deal;
const record = data.airtableRecord;

console.log(`[AIRTABLE] Upserting ${deal.propertyId}`);

// In production: Call Airtable API
// Check if record exists, update or create

// Simulated response
const existingRecord = Math.random() > 0.7; // 30% chance record exists

const airtableResponse = {
  id: `rec${Math.random().toString(36).substr(2, 14)}`,
  createdTime: existingRecord ? new Date(Date.now() - 86400000).toISOString() : new Date().toISOString(),
  fields: record.fields,
  operation: existingRecord ? 'updated' : 'created'
};

return [{
  json: {
    deal: deal,
    airtableResponse: airtableResponse,
    synced: true
  }
}];

// Format deal for Google Sheets
const deal = $input.item.json.deal;

// Google Sheets row format (matches column headers)
const sheetRow = [
  deal.propertyId,
  new Date(deal.scoredAt).toLocaleDateString(),
  deal.dealScore,
  deal.dealTier,
  deal.propertyType,
  deal.address,
  deal.city,
  deal.state,
  deal.zipCode,
  deal.listPrice,
  parseFloat(deal.capRate),
  parseFloat(deal.irr),
  deal.squareFeet,
  Math.round(deal.listPrice / deal.squareFeet),
  deal.ownerName,
  deal.ownerEmail,
  deal.ownerPhone,
  deal.recommendation,
  'New',
  new Date().toISOString()
];

return [{
  json: {
    deal: deal,
    sheetRow: sheetRow,
    spreadsheetId: process.env.GOOGLE_SHEETS_DEALS_ID || 'demo-spreadsheet-id',
    sheetName: 'Active Deals'
  }
}];

// Simulate Google Sheets append operation
const data = $input.item.json;

console.log(`[GOOGLE SHEETS] Appending row for ${data.deal.propertyId}`);

// In production: Call Google Sheets API
// POST to https://sheets.googleapis.com/v4/spreadsheets/{spreadsheetId}/values/{range}:append

const sheetsResponse = {
  spreadsheetId: data.spreadsheetId,
  tableRange: `${data.sheetName}!A1:T1000`,
  updates: {
    spreadsheetId: data.spreadsheetId,
    updatedRange: `${data.sheetName}!A${Math.floor(Math.random() * 100) + 2}:T${Math.floor(Math.random() * 100) + 2}`,
    updatedRows: 1,
    updatedColumns: 20,
    updatedCells: 20
  }
};

return [{
  json: {
    deal: data.deal,
    sheetsResponse: sheetsResponse,
    synced: true
  }
}];

// Create owner contact record
const deal = $input.item.json.deal;

const ownerRecord = {
  fields: {
    'Contact ID': `contact-${deal.propertyId}`,
    'Name': deal.ownerName,
    'Email': deal.ownerEmail,
    'Phone': deal.ownerPhone,
    'Type': 'Property Owner',
    'Properties Owned': [deal.propertyId], // Link to property record
    'First Contact Date': new Date().toISOString(),
    'Contact Quality': deal.ownerEmail ? 'High' : 'Medium',
    'Status': 'Active',
    'Source': 'PropFlow Engine',
    'Created': new Date().toISOString()
  }
};

return [{
  json: {
    deal: deal,
    ownerRecord: ownerRecord
  }
}];

// Sync owner contact to Airtable Contacts table
const data = $input.item.json;

console.log(`[AIRTABLE CONTACTS] Upserting ${data.ownerRecord.fields.Name}`);

// In production: Call Airtable API for Contacts base

const contactResponse = {
  id: `rec${Math.random().toString(36).substr(2, 14)}`,
  createdTime: new Date().toISOString(),
  fields: data.ownerRecord.fields,
  operation: Math.random() > 0.5 ? 'updated' : 'created'
};

return [{
  json: {
    deal: data.deal,
    contactResponse: contactResponse,
    synced: true
  }
}];

// Update database sync status
const allResults = $input.all();

const syncSummary = {
  totalDeals: allResults.length / 3, // Each deal has 3 sync operations
  airtableDeals: allResults.filter(r => r.json.airtableResponse).length,
  googleSheets: allResults.filter(r => r.json.sheetsResponse).length,
  contacts: allResults.filter(r => r.json.contactResponse).length,
  timestamp: new Date().toISOString(),
  success: true
};

console.log('[DATABASE] Updating sync status:', syncSummary);

// In production: Update database records with crm_synced = true

return [{ json: syncSummary }];

// Generate dashboard update
const summary = $input.first().json;

const dashboardUpdate = {
  type: 'crm_sync_complete',
  timestamp: new Date().toISOString(),
  metrics: {
    dealsSynced: summary.totalDeals,
    airtableUpdates: summary.airtableDeals,
    sheetsUpdates: summary.googleSheets,
    contactsCreated: summary.contacts
  },
  message: `CRM sync complete: ${summary.totalDeals} deals synced to Airtable and Google Sheets`,
  nextSync: new Date(Date.now() + 2 * 60 * 60 * 1000).toISOString() // Next sync in 2 hours
};

console.log('Dashboard update prepared:', dashboardUpdate);

return [{ json: dashboardUpdate }];

// Activity logging
const update = $input.first().json;

const activityLog = {
  timestamp: new Date().toISOString(),
  workflow: 'CRM Sync Workflow',
  status: 'completed',
  metrics: update.metrics,
  message: update.message
};

console.log('Workflow completed:', JSON.stringify(activityLog, null, 2));

return [{ json: activityLog }];
